"""Independent analytic solver fixtures, never generated by the IFC exporter."""

import hashlib
import json
import os
from pathlib import Path
from ifc_to_fds.modules.verification.application.engine import solver_gates
from ifc_to_fds.domain.validation.model import AuditConfig
from ifc_to_fds.modules.simulation.api import POLICY, VERSION, adapter_digest
from ifc_to_fds.modules.simulation.api import fixture_cases, fixture_text


def certify(executable, output, *, solver_runner=None):
    root = Path(output).resolve()
    root.mkdir(parents=True, exist_ok=True)
    cases = fixture_cases()
    records = {}
    for name, boxes in cases.items():
        text = fixture_text(name, boxes)
        config = AuditConfig(
            solver_executable=str(executable),
            solver_evidence_directory=str(root / "runs"),
        )
        solver, effective = (solver_runner or solver_gates)(text, config)
        expected = {
            f"box{i}": [round(v / 0.2) * 0.2 for v in bounds]
            for i, bounds in enumerate(boxes)
        }
        actual = effective.evidence.get("effective_bounds", {})
        if name == "rejected":
            matched = solver.status == "FAIL"
        elif name in ("thin", "closed_passage"):
            matched = solver.status == "PASS" and effective.status == "FAIL"
        else:
            matched = (
                solver.status == "PASS"
                and effective.status == "PASS"
                and actual.keys() == expected.keys()
                and all(
                    abs(a - b) < 1e-8
                    for key in expected
                    for a, b in zip(actual[key], expected[key])
                )
            )
        records[name] = dict(
            expected_matched=matched,
            expected_effective_bounds=expected,
            solver_status=getattr(solver.status, "value", str(solver.status)),
            effective_status=getattr(effective.status, "value", str(effective.status)),
            reason=effective.reason,
            directory=os.path.relpath(solver.evidence.get("directory", root), root),
            fds_sha256=hashlib.sha256(text.encode()).hexdigest(),
        )
        (root / "progress.json").write_text(
            json.dumps(records, indent=2), encoding="utf-8"
        )
    certificate = dict(
        policy=POLICY,
        policy_version=VERSION,
        solver_version="6.11.1",
        adapter_sha256=adapter_digest(),
        solver_sha256=hashlib.sha256(Path(executable).read_bytes()).hexdigest(),
        cases=records,
    )
    target = root / "certificate.json"
    target.write_text(json.dumps(certificate, indent=2), encoding="utf-8")
    return target, all(c["expected_matched"] for c in records.values())
